<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue'
import {Save,Plus,BetweenHorizontalStart,MinusCircle,KeyRound,ArrowUp,ArrowDown,RefreshCw,X,Square,LoaderCircle,Copy} from '@lucide/vue'
import {api,errorText,type AdminRequest,type AdminResult,type Profile,type QueryResult} from './api'
import SearchableSelect from './SearchableSelect.vue'
import {newDesign,newField,parseDesign,designSQL,triggerScript,uid,types,actions,columnNames,same,quoteText,renameReferences,convertSQLStrings,type TableDesign,type Field,type DesignTrigger} from './tableDesigner'
import {quoteIdentifier as qi,sqlText} from './tableData'
const props=defineProps<{profile:Profile;database:string;table?:string;connected:boolean;sessionKey:string;active:boolean}>()
const emit=defineEmits<{dirty:[value:boolean];saved:[name:string];confirm:[request:{title:string;body:string;label:string;action:()=>void|Promise<void>}]}>()
const designerID='designer-'+uid()
const knownNames=new Map<string,string>()
const schemaDefaults=ref({charset:'',collation:''})
const fieldLayout=ref<HTMLElement>(),layoutHeight=ref(0),preferredHeight=ref(216)
let stopPropertyResize:(()=>void)|undefined
try{const stored=JSON.parse(localStorage.getItem('bajiu.designer-properties.v1')??'null');if(stored?.version===1&&typeof stored.height==='number'&&Number.isFinite(stored.height))preferredHeight.value=Math.max(90,Math.min(1200,stored.height))}catch{}
const propertyMaximum=computed(()=>Math.max(90,(layoutHeight.value||400)-100))
const propertyHeight=computed(()=>Math.min(preferredHeight.value,propertyMaximum.value))
const defaultModes=[{value:'none',label:'无默认值'},{value:'null',label:'NULL'},{value:'value',label:'文本值'},{value:'expression',label:'SQL 表达式'}]
const defaultOption={value:'',label:'默认'}
function persistProperties(){try{localStorage.setItem('bajiu.designer-properties.v1',JSON.stringify({version:1,height:preferredHeight.value}))}catch{}}
function resizeProperties(event:PointerEvent){if(event.button!==0)return;event.preventDefault();stopPropertyResize?.();const start=event.clientY,height=propertyHeight.value,handle=event.currentTarget as HTMLElement,cursor=document.body.style.cursor,select=document.body.style.userSelect;handle.setPointerCapture?.(event.pointerId);document.body.style.cursor='row-resize';document.body.style.userSelect='none';const move=(e:PointerEvent)=>{preferredHeight.value=Math.max(90,Math.min(propertyMaximum.value,height+start-e.clientY))};const finish=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',finish);window.removeEventListener('blur',finish);try{handle.releasePointerCapture?.(event.pointerId)}catch{}document.body.style.cursor=cursor;document.body.style.userSelect=select;stopPropertyResize=undefined;persistProperties()};document.addEventListener('pointermove',move);document.addEventListener('pointerup',finish,{once:true});document.addEventListener('pointercancel',finish,{once:true});window.addEventListener('blur',finish,{once:true});stopPropertyResize=finish}
function propertyKeys(event:KeyboardEvent){if(!['ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();preferredHeight.value=Math.max(90,Math.min(propertyMaximum.value,event.key==='Home'?216:propertyHeight.value+(event.key==='ArrowUp'?12:-12)));persistProperties()}
watch(fieldLayout,(element,_,cleanup)=>{if(!element)return;const update=()=>{layoutHeight.value=element.clientHeight};const observer=typeof ResizeObserver==='function'?new ResizeObserver(update):undefined;observer?.observe(element);window.addEventListener('resize',update);update();cleanup(()=>{observer?.disconnect();window.removeEventListener('resize',update);stopPropertyResize?.()})},{flush:'post'})
const model=ref<TableDesign>(newDesign()),original=ref<TableDesign>(),originalDDL=ref(''),baseline=ref(''),tableName=ref(props.table??''),savedName=ref(props.table??'')
const tabs=['字段','索引','外键','触发器','选项','注释','SQL 预览'],tab=ref('字段'),selected=ref(0),indexSelected=ref(-1),foreignSelected=ref(-1),triggerSelected=ref(-1)
const running=ref(false),loaded=ref(false),uncertain=ref(false),sessionChanged=ref(false),error=ref(''),message=ref(''),catalog=ref<(string|null)[][]>([]),engines=ref(['InnoDB','MyISAM','MEMORY','ARCHIVE','CSV']),host=ref<HTMLElement>()
class DesignQueryError extends Error{constructor(message:string,readonly completed:number){super(message)}}
let task='',disposed=false
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const state=computed(()=>JSON.stringify([tableName.value,model.value]))
const dirty=computed(()=>loaded.value&&state.value!==baseline.value)
const field=computed(()=>model.value.fields[selected.value])
const charsets=computed(()=>[...new Set(catalog.value.map(r=>r[1]??''))].filter(Boolean).sort())
const collations=computed(()=>catalog.value.filter(r=>r[1]===model.value.options.charset).map(r=>r[0]??''))
const locked=computed(()=>running.value||!loaded.value||!props.connected||sessionChanged.value||uncertain.value)
const sqlState=computed(()=>{try{const table=designSQL(props.database,tableName.value,model.value,original.value),triggers=triggerScript(props.database,tableName.value,model.value,original.value);const body=[table,triggers].filter(Boolean).join('\n\n');if(!/^[a-z0-9_,]*$/i.test(model.value.sqlMode))throw new Error('服务器 SQL 模式格式无效');return {sql:body?'SET SESSION sql_mode = '+quoteText(model.value.sqlMode,'NO_BACKSLASH_ESCAPES')+';\n\n'+body:'',error:''}}catch(e){return {sql:'',error:errorText(e)}}})
const currentTrigger=computed(()=>model.value.triggers[triggerSelected.value])
function recordBaseline(){baseline.value=state.value}
function textField(item:Field){return /^(?:char|varchar|(?:tiny|medium|long)?text|enum|set)$/i.test(item.type)}
function charsetForCollation(value:string){return catalog.value.find(row=>row[0]===value)?.[1]??value.split('_')[0]??''}
function defaultCollation(charset:string){if(schemaDefaults.value.charset===charset)return schemaDefaults.value.collation;if(model.value.options.charset===charset&&catalog.value.some(row=>row[0]===model.value.options.collation&&row[1]===charset))return model.value.options.collation;return catalog.value.find(row=>row[1]===charset&&row[3]==='Yes')?.[0]??catalog.value.find(row=>row[1]===charset)?.[0]??''}
function fieldCollations(item:Field){return catalog.value.filter(row=>row[1]===(item.charset||model.value.options.charset||schemaDefaults.value.charset)).map(row=>row[0]??'')}
function fieldCharset(item:Field,value:string){item.charset=value;if(charsets.value.includes(value)&&!fieldCollations(item).includes(item.collation))item.collation=defaultCollation(value)}
function fieldCollation(item:Field,value:string){item.collation=value;const charset=catalog.value.find(row=>row[0]===value)?.[1];if(charset)item.charset=charset}
function tableCharset(value:string){model.value.options.charset=value;if(charsets.value.includes(value)&&!collations.value.includes(model.value.options.collation))model.value.options.collation=defaultCollation(value)}
function tableCollation(value:string){model.value.options.collation=value;const charset=catalog.value.find(row=>row[0]===value)?.[1];if(charset)model.value.options.charset=charset}
function fillFieldDefaults(item:Field){if(textField(item)){item.charset=model.value.options.charset||schemaDefaults.value.charset;item.collation=model.value.options.collation||defaultCollation(item.charset)}}

async function request(request:AdminRequest):Promise<AdminResult>{if(disposed)throw new Error('设计器已关闭');task=crypto.randomUUID();try{const result=await api.DatabaseAdmin(task,props.profile.id,props.database,request);if(disposed)throw new Error('设计器已关闭');if(result.error)throw new DesignQueryError(result.error,result.completed);return result}finally{task=''}}
async function perform(action:()=>Promise<void>){if(running.value)return;running.value=true;error.value='';message.value='';try{await action()}catch(e){if(!disposed)error.value=errorText(e)}finally{running.value=false}}
async function cancel(){if(task)await api.CancelDatabaseTask(task).catch(e=>{error.value=errorText(e)})}
function rowsByName(result:QueryResult|undefined){return (result?.rows??[]).map(row=>Object.fromEntries((result?.columns??[]).map((c,i)=>[c,row[i]??''])))}
async function read(){
 if(!props.connected)throw new Error('请先打开连接')
 const readSession=props.sessionKey
 const schema=await request({operation:'schema'}),pair=schema.results[0]?.rows[0];if(!pair?.[0]||!pair?.[1])throw new Error('无法读取数据库默认字符集和排序规则');schemaDefaults.value={charset:pair[0],collation:pair[1]}
 if(savedName.value){
  const qualified=qi(props.database)+'.'+qi(savedName.value)
  const result=await request({operation:'query',sql:'SHOW CREATE TABLE '+qualified+';\nSELECT @@SESSION.sql_mode AS sql_mode;\nSELECT TRIGGER_NAME,ACTION_TIMING,EVENT_MANIPULATION,ACTION_STATEMENT FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='+sqlText(props.database)+' AND EVENT_OBJECT_TABLE='+sqlText(savedName.value)+' ORDER BY TRIGGER_NAME;\nSHOW FULL COLUMNS FROM '+qualified+';\nSELECT TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA='+sqlText(props.database)+' AND TABLE_NAME='+sqlText(savedName.value)+' AND TABLE_TYPE=\'BASE TABLE\';'})
  const ddl=result.results[0]?.rows[0]?.[1];if(!ddl||result.results.length!==5||typeof result.results[1]?.rows[0]?.[0]!=='string'||result.results.some(r=>r.truncated))throw new Error('表结构信息不完整，请在查询编辑器中查看')
  const design=parseDesign(ddl,result.results[1]?.rows[0]?.[0]??'');const tableCollation=result.results[4]?.rows[0]?.[0];if(!tableCollation)throw new Error('无法读取表排序规则');design.options.collation=tableCollation;design.options.charset=charsetForCollation(tableCollation);const fullColumns=rowsByName(result.results[3]);for(const field of design.fields){if(!textField(field))continue;const collation=fullColumns.find(column=>column.Field===field.name)?.Collation;if(!collation)throw new Error('无法读取字段排序规则：'+field.name);field.charset=charsetForCollation(collation);field.collation=collation}
  design.triggers=(result.results[2]?.rows??[]).map(row=>({id:uid(),name:row[0]??'',timing:row[1] as DesignTrigger['timing'],event:row[2] as DesignTrigger['event'],body:row[3]??''}))
  for(const trigger of design.triggers){const response=await request({operation:'query',sql:'SHOW CREATE TRIGGER '+qi(props.database)+'.'+qi(trigger.name)+';'});const create=rowsByName(response.results[0])[0];trigger.raw=create?.['SQL Original Statement'];trigger.sourceBody=trigger.body;trigger.body=convertSQLStrings(trigger.body,create?.sql_mode??design.sqlMode,design.sqlMode);if(!trigger.raw)throw new Error('无法读取触发器完整定义：'+trigger.name)}
  if(!props.connected||props.sessionKey!==readSession)throw new Error('连接会话已变化，请重新加载结构')
  model.value=design;original.value=clone(design);originalDDL.value=ddl;tableName.value=savedName.value
 }else{const design=newDesign(),result=await request({operation:'query',sql:'SELECT @@SESSION.sql_mode AS sql_mode;'});if(!props.connected||props.sessionKey!==readSession)throw new Error('连接会话已变化，请重新加载结构');const mode=result.results[0]?.rows[0]?.[0];if(typeof mode!=='string')throw new Error('无法读取服务器 SQL 模式');design.sqlMode=mode;design.options.charset=pair[0];design.options.collation=pair[1];model.value=design;for(const field of model.value.fields)fillFieldDefaults(field);original.value=undefined}
 knownNames.clear();for(const field of model.value.fields)knownNames.set(field.id,field.name)
 selected.value=0;indexSelected.value=foreignSelected.value=triggerSelected.value=-1;loaded.value=true;uncertain.value=false;sessionChanged.value=false;recordBaseline()
}
async function loadCatalog(){try{const result=await request({operation:'catalog'});catalog.value=result.results[0]?.rows??[]}catch{message.value='字符集列表暂不可用，可在选项中直接输入。'}}
function reload(){const action=()=>perform(read);if(dirty.value)emit('confirm',{title:'重新加载表结构？',body:'将放弃当前设计草稿，重新读取服务器结构。',label:'重新加载',action});else void action()}
function addField(insert=false){const index=insert?Math.max(0,selected.value):model.value.fields.length;const item=newField();fillFieldDefaults(item);model.value.fields.splice(index,0,item);selected.value=index;tab.value='字段';void nextTick(()=>host.value?.querySelector<HTMLInputElement>('[data-field-selected] input')?.focus())}
function removeField(){const current=field.value;if(!current)return;emit('confirm',{title:'从设计中删除字段？',body:'删除字段“'+(current.name||'未命名字段')+'”？保存后才会应用到数据库，请同时检查相关索引和外键。',label:'删除字段',action:()=>{const index=model.value.fields.findIndex(item=>item.id===current.id);if(index<0)return;model.value.fields.splice(index,1);selected.value=Math.max(0,Math.min(index,model.value.fields.length-1))}})}
function removeItem(kind:'index'|'foreign'|'trigger'){const array=kind==='index'?model.value.indexes:kind==='foreign'?model.value.foreignKeys:model.value.triggers,index=kind==='index'?indexSelected.value:kind==='foreign'?foreignSelected.value:triggerSelected.value,item=array[index];if(!item)return;const name=kind==='index'?'索引':kind==='foreign'?'外键':'触发器';emit('confirm',{title:'从设计中删除'+name+'？',body:'删除'+name+'“'+(item.name||'未命名')+'”？保存后才会应用到数据库。',label:'删除'+name,action:()=>{const current=array.findIndex(value=>value.id===item.id);if(current<0)return;array.splice(current,1);if(kind==='index')indexSelected.value=-1;else if(kind==='foreign')foreignSelected.value=-1;else triggerSelected.value=-1}})}
function moveField(direction:number){const target=selected.value+direction;if(target<0||target>=model.value.fields.length)return;const [current]=model.value.fields.splice(selected.value,1);model.value.fields.splice(target,0,current!);selected.value=target}
function primary(field:Field){try{return model.value.indexes.some(index=>index.kind==='PRIMARY'&&columnNames(index.fields).includes(field.name))}catch{return false}}
function togglePrimary(target=field.value){if(!target)return;if(!target.name){error.value='请先填写字段名称';return}let index=model.value.indexes.find(v=>v.kind==='PRIMARY');if(!index){index={id:uid(),name:'PRIMARY',kind:'PRIMARY',fields:'',method:'',comment:''};model.value.indexes.push(index)}let names:string[];try{names=columnNames(index.fields)}catch{error.value='请先修正索引标签中的主键字段列表';return}const position=names.indexOf(target.name);if(position>=0){const primaryIndex=index;emit('confirm',{title:'取消字段主键？',body:'取消字段“'+target.name+'”的主键设置？保存后才会应用到数据库。',label:'取消主键',action:()=>{const remaining=columnNames(primaryIndex.fields).filter(name=>name!==target.name);primaryIndex.fields=remaining.map(qi).join(', ');if(!remaining.length){const i=model.value.indexes.indexOf(primaryIndex);if(i>=0)model.value.indexes.splice(i,1)}}});return}else{names.push(target.name);target.notNull=true}index.fields=names.map(qi).join(', ')}
function changeType(current:Field){if(!types.includes(current.type.toLowerCase()))return;if(textField(current)){if(!current.charset)fillFieldDefaults(current)}else{current.charset='';current.collation=''};if(['varchar','char','varbinary','binary'].includes(current.type)&&!current.length)current.length='255';else if(!['varchar','char','varbinary','binary','decimal','float','double','bit','int','smallint','mediumint','tinyint','bigint','enum','set','time','datetime','timestamp','year'].includes(current.type)){current.length='';current.decimals=''}}
function virtualChanged(current:Field){if(current.generated){current.autoIncrement=false;current.defaultMode='none'}}
function addIndex(){model.value.indexes.push({id:uid(),name:'idx_'+(model.value.indexes.length+1),kind:'NORMAL',fields:'',method:'',comment:''});indexSelected.value=model.value.indexes.length-1}
function addForeign(){model.value.foreignKeys.push({id:uid(),name:'fk_'+(model.value.foreignKeys.length+1),fields:'',database:props.database,table:'',references:'',onDelete:'',onUpdate:''});foreignSelected.value=model.value.foreignKeys.length-1}
function addTrigger(){model.value.triggers.push({id:uid(),name:'trg_'+(model.value.triggers.length+1),timing:'BEFORE',event:'INSERT',body:'BEGIN\n  SET NEW.column_name = NEW.column_name;\nEND'});triggerSelected.value=model.value.triggers.length-1}
async function save(){
 if(locked.value)return
 if(sqlState.value.error){error.value=sqlState.value.error;tab.value=tableName.value?'SQL 预览':'选项';return}
 if(!sqlState.value.sql){message.value='没有需要保存的修改';return}
 const sql=sqlState.value.sql,expectedDDL=originalDDL.value,expectedName=savedName.value,name=tableName.value,saveSession=props.sessionKey
 await perform(async()=>{
  if(!props.connected||sessionChanged.value||uncertain.value||sql!==sqlState.value.sql)throw new Error('设计或连接状态已变化，请重新核对后保存')
  if(expectedName){const latest=await api.TableDDL(props.profile.id,props.database,expectedName);if(latest!==expectedDDL)throw new Error('服务器表结构已变化，请重新加载后再修改');const current=await request({operation:'query',sql:'SELECT TRIGGER_NAME,ACTION_TIMING,EVENT_MANIPULATION,ACTION_STATEMENT FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='+sqlText(props.database)+' AND EVENT_OBJECT_TABLE='+sqlText(expectedName)+' ORDER BY TRIGGER_NAME;'});if(current.results[0]?.truncated||!same(current.results[0]?.rows??[],original.value?.triggers.map(t=>[t.name,t.timing,t.event,t.sourceBody??t.body])??[]))throw new Error('服务器触发器已变化，请重新加载后再修改')}
  for(const old of original.value?.triggers??[]){if(model.value.triggers.some(t=>t.id===old.id&&same(t,old)))continue;const response=await request({operation:'query',sql:'SHOW CREATE TRIGGER '+qi(props.database)+'.'+qi(old.name)+';'});if(rowsByName(response.results[0])[0]?.['SQL Original Statement']!==old.raw)throw new Error('触发器定义或执行账户已变化，请重新加载后再修改')}
  if(!props.connected||props.sessionKey!==saveSession)throw new Error('连接会话已变化，请重新加载结构')
  try{await request({operation:'query',sql,sqlMode:model.value.sqlMode})}catch(e){const notApplied=e instanceof DesignQueryError&&e.completed<=1;if(!notApplied){uncertain.value=true;if(!expectedName){savedName.value=name;emit('saved',name)}}throw new Error(errorText(e)+(notApplied?'；服务器拒绝了当前结构语句，请修正设计后重试。':'；操作可能已部分执行，请重新加载核对后继续。'))}
  savedName.value=name;emit('saved',name)
  try{await read();message.value='表结构已保存'}catch(e){uncertain.value=true;throw new Error('保存已执行，但重新读取失败：'+errorText(e)+'。请重新加载核对。')}
 })
}
async function copySQL(){try{if(sqlState.value.error)throw new Error(sqlState.value.error);await navigator.clipboard.writeText(sqlState.value.sql);message.value='已复制 SQL'}catch(e){error.value=errorText(e)}}
watch(()=>model.value.fields.map(f=>[f.id,f.name]),()=>{for(const field of model.value.fields){const before=knownNames.get(field.id);if(before&&field.name&&before!==field.name){for(const index of model.value.indexes)index.fields=renameReferences(index.fields,before,field.name,model.value.sqlMode);for(const fk of model.value.foreignKeys){fk.fields=renameReferences(fk.fields,before,field.name,model.value.sqlMode);if(fk.table===tableName.value&&(!fk.database||fk.database===props.database))fk.references=renameReferences(fk.references,before,field.name,model.value.sqlMode)}}if(field.name)knownNames.set(field.id,field.name)}},{flush:'sync'})
watch(dirty,value=>emit('dirty',value),{immediate:true})
watch(()=>props.sessionKey,(value,old)=>{if(old&&value!==old)sessionChanged.value=true})
watch(()=>props.connected,connected=>{if(connected&&!loaded.value)void perform(async()=>{await loadCatalog();await read()})})
onMounted(()=>{if(props.connected)void perform(async()=>{await loadCatalog();await read()}).then(()=>nextTick(()=>{if(props.active&&!savedName.value)host.value?.querySelector<HTMLInputElement>('[data-field-selected] input')?.focus()}))})
onUnmounted(()=>{disposed=true;stopPropertyResize?.();if(task)void api.CancelDatabaseTask(task).catch(()=>{})})
</script>
<template><section ref="host" class="table-designer" :aria-label="savedName?'设计表 '+savedName:'新建表'" @keydown.ctrl.s.prevent="save" @keydown.meta.s.prevent="save">
 <header class="designer-toolbar" role="toolbar" aria-label="表设计操作"><button @click="save" :disabled="locked||(!dirty&&!!savedName)"><Save :size="15"/>保存</button><span class="designer-divider"></span><button @click="addField()" :disabled="locked"><Plus :size="15" class="add-color"/>添加字段</button><button @click="addField(true)" :disabled="locked"><BetweenHorizontalStart :size="15"/>插入字段</button><button @click="removeField" :disabled="locked||!field"><MinusCircle :size="15" class="designer-danger"/>删除字段</button><span class="designer-divider"></span><button @click="togglePrimary()" :disabled="locked||!field"><KeyRound :size="15"/>主键</button><span class="designer-divider"></span><button @click="moveField(-1)" :disabled="locked||selected<=0"><ArrowUp :size="15"/>上移</button><button @click="moveField(1)" :disabled="locked||selected>=model.fields.length-1"><ArrowDown :size="15"/>下移</button><button class="designer-reload" @click="reload" :disabled="running||!connected" title="重新加载结构"><RefreshCw :size="15"/></button></header>
 <nav class="designer-tabs" role="tablist" aria-label="表设计分类"><button v-for="name in tabs" :key="name" role="tab" :aria-selected="tab===name" :class="{active:tab===name}" @click="tab=name">{{name}}</button></nav>
 <div v-if="running||error||message||sessionChanged||!connected||uncertain" class="designer-feedback"><span v-if="running" role="status"><LoaderCircle :size="13" class="spin"/>正在处理…<button class="tiny-button" @click="cancel" aria-label="停止操作"><Square :size="12"/></button></span><p v-if="error" class="db-tools-error" role="alert"><span>{{error}}</span><button class="tiny-button" @click="error=''" aria-label="关闭错误提示"><X :size="14"/></button></p><p v-if="message" class="db-tools-message" role="status"><span>{{message}}</span><button class="tiny-button" @click="message=''" aria-label="关闭操作提示"><X :size="14"/></button></p><p v-if="!connected||sessionChanged||uncertain" class="table-data-notice">{{!connected?'连接已关闭，设计草稿已保留。':uncertain?'上次操作结果尚未核对，请重新加载结构。':'连接会话已变化，请重新加载结构。'}}</p></div>
 <div v-if="tab==='字段'" ref="fieldLayout" class="designer-field-layout"><div class="designer-grid-wrap"><table class="designer-grid" aria-label="字段设计"><colgroup><col style="width:32px"/><col style="width:260px"/><col style="width:160px"/><col style="width:75px"/><col style="width:75px"/><col style="width:80px"/><col style="width:75px"/><col style="width:65px"/><col style="width:180px"/><col style="width:240px"/></colgroup><thead><tr><th></th><th>名称</th><th>类型</th><th>长度</th><th>小数点</th><th>不是 null</th><th>虚拟</th><th>键</th><th>字符集</th><th>排序规则</th></tr></thead><tbody><tr v-for="(item,i) in model.fields" :key="item.id" :data-field-selected="selected===i?'':undefined" :class="{selected:selected===i}" @focusin="selected=i" @click="selected=i"><td class="designer-row-number">{{i+1}}</td><td><input v-model="item.name" :aria-label="'字段 '+(i+1)+' 名称'" :disabled="locked" maxlength="64"/></td><td><SearchableSelect :id="designerID+'-type-'+item.id" :label="'字段 '+(i+1)+' 类型'" v-model="item.type" :options="types" :disabled="locked" @change="changeType(item)"/></td><td><input v-model="item.length" :aria-label="item.name+'长度'" :disabled="locked"/></td><td><input v-model="item.decimals" :aria-label="item.name+'小数点'" :disabled="locked"/></td><td class="designer-check"><input type="checkbox" v-model="item.notNull" :aria-label="item.name+'不是 NULL'" :disabled="locked||primary(item)"/></td><td class="designer-check"><input type="checkbox" :checked="!!item.generated" :aria-label="item.name+'虚拟列'" :disabled="locked" @change="item.generated=($event.target as HTMLInputElement).checked?'VIRTUAL':'';virtualChanged(item)"/></td><td class="designer-check"><button class="tiny-button" @click.stop="togglePrimary(item)" :disabled="locked" :aria-label="item.name+'主键'" :aria-pressed="primary(item)"><KeyRound v-if="primary(item)" :size="15"/></button></td><td><SearchableSelect :id="designerID+'-field-charset-'+item.id" :label="item.name+'字符集'" :modelValue="item.charset" @update:modelValue="fieldCharset(item,$event)" :options="charsets" :disabled="locked||!textField(item)"/></td><td><SearchableSelect :id="designerID+'-field-collation-'+item.id" :label="item.name+'排序规则'" :modelValue="item.collation" @update:modelValue="fieldCollation(item,$event)" :options="fieldCollations(item)" :disabled="locked||!textField(item)"/></td></tr></tbody></table></div>
 <div v-if="field" class="designer-property-splitter" role="separator" aria-label="调整字段属性区域高度" aria-orientation="horizontal" tabindex="0" :aria-valuenow="propertyHeight" aria-valuemin="90" :aria-valuemax="propertyMaximum" @pointerdown="resizeProperties" @keydown="propertyKeys"></div><div class="designer-properties" v-if="field" :style="{height:propertyHeight+'px',flexBasis:propertyHeight+'px'}"><div class="designer-property"><label>默认</label><SearchableSelect :id="designerID+'-default-mode'" label="默认值类型" :modelValue="field.defaultMode" @update:modelValue="field.defaultMode=$event as Field['defaultMode']" :options="defaultModes" :allowCustom="false" :disabled="locked||!!field.generated"/><SearchableSelect v-if="field.defaultMode==='value'||field.defaultMode==='expression'" :id="designerID+'-default-value'" label="字段默认值" v-model="field.defaultValue" :options="['CURRENT_TIMESTAMP','0']" :disabled="locked||!!field.generated"/></div><div class="designer-property"><label>属性</label><label class="native-check"><input v-model="field.autoIncrement" type="checkbox" :disabled="locked||!!field.generated"/>自动递增</label><label class="native-check"><input v-model="field.unsigned" type="checkbox" :disabled="locked"/>无符号</label><template v-if="field.generated"><SearchableSelect :id="designerID+'-generated'" label="生成列存储方式" :modelValue="field.generated" @update:modelValue="field.generated=$event as Field['generated']" :options="['VIRTUAL','STORED']" :allowCustom="false" :disabled="locked"/><input v-model="field.expression" :disabled="locked" placeholder="生成列表达式" aria-label="生成列表达式"/></template></div><div class="designer-property"><label>字符集</label><SearchableSelect :id="designerID+'-property-charset'" label="字段字符集" :modelValue="field.charset" @update:modelValue="fieldCharset(field,$event)" :options="charsets" :disabled="locked||!textField(field)"/><label>排序规则</label><SearchableSelect :id="designerID+'-property-collation'" label="字段排序规则" :modelValue="field.collation" @update:modelValue="fieldCollation(field,$event)" :options="fieldCollations(field)" :disabled="locked||!textField(field)"/></div><div class="designer-property"><label>注释</label><textarea v-model="field.comment" :disabled="locked" aria-label="字段注释" rows="3"/></div><details><summary>高级属性（SQL）</summary><input v-model="field.advanced" :disabled="locked" aria-label="字段高级属性" placeholder="例如 ON UPDATE CURRENT_TIMESTAMP"/></details></div></div>
 <template v-else-if="tab==='索引'"><div class="designer-section-tools"><button class="native-button" @click="addIndex" :disabled="locked"><Plus :size="14"/>添加索引</button><button class="native-button" @click="removeItem('index')" :disabled="locked||indexSelected<0"><MinusCircle :size="14"/>删除索引</button><span>字段可填写 id, name(32)；支持 ASC / DESC。</span></div><div class="designer-grid-wrap"><table class="designer-grid designer-index-grid" aria-label="索引设计"><thead><tr><th>名称</th><th>类型</th><th>字段</th><th>方法</th><th>注释</th></tr></thead><tbody><tr v-for="(index,i) in model.indexes" :key="index.id" :class="{selected:indexSelected===i}" @focusin="indexSelected=i" @click="indexSelected=i"><td><input v-model="index.name" :disabled="locked||index.kind==='PRIMARY'" aria-label="索引名称"/></td><td><SearchableSelect :id="designerID+'-index-kind-'+index.id" label="索引类型" :modelValue="index.kind" @update:modelValue="index.kind=$event as typeof index.kind" :options="['NORMAL','UNIQUE','PRIMARY','FULLTEXT','SPATIAL']" :allowCustom="false" :disabled="locked"/></td><td><input v-model="index.fields" :disabled="locked" aria-label="索引字段"/></td><td><SearchableSelect :id="designerID+'-index-method-'+index.id" label="索引方法" v-model="index.method" :options="[defaultOption,'BTREE','HASH']" :allowCustom="false" :disabled="locked"/></td><td><textarea v-model="index.comment" :disabled="locked" aria-label="索引注释" rows="2"/></td></tr></tbody></table></div></template>
 <template v-else-if="tab==='外键'"><div class="designer-section-tools"><button class="native-button" @click="addForeign" :disabled="locked"><Plus :size="14"/>添加外键</button><button class="native-button" @click="removeItem('foreign')" :disabled="locked||foreignSelected<0"><MinusCircle :size="14"/>删除外键</button></div><div class="designer-grid-wrap"><table class="designer-grid designer-fk-grid" aria-label="外键设计"><thead><tr><th>名称</th><th>字段</th><th>引用数据库</th><th>引用表</th><th>引用字段</th><th>删除时</th><th>更新时</th></tr></thead><tbody><tr v-for="(fk,i) in model.foreignKeys" :key="fk.id" :class="{selected:foreignSelected===i}" @focusin="foreignSelected=i" @click="foreignSelected=i"><td><input v-model="fk.name" :disabled="locked" aria-label="外键名称"/></td><td><input v-model="fk.fields" :disabled="locked" aria-label="外键字段"/></td><td><input v-model="fk.database" :disabled="locked" aria-label="引用数据库"/></td><td><input v-model="fk.table" :disabled="locked" aria-label="引用表"/></td><td><input v-model="fk.references" :disabled="locked" aria-label="引用字段"/></td><td><SearchableSelect :id="designerID+'-fk-onDelete-'+fk.id" label="删除动作" v-model="fk.onDelete" :options="[defaultOption,...actions.filter(Boolean)]" :allowCustom="false" :disabled="locked"/></td><td><SearchableSelect :id="designerID+'-fk-onUpdate-'+fk.id" label="更新动作" v-model="fk.onUpdate" :options="[defaultOption,...actions.filter(Boolean)]" :allowCustom="false" :disabled="locked"/></td></tr></tbody></table></div></template>
 <template v-else-if="tab==='触发器'"><div class="designer-section-tools"><button class="native-button" @click="addTrigger" :disabled="locked"><Plus :size="14"/>添加触发器</button><button class="native-button" @click="removeItem('trigger')" :disabled="locked||triggerSelected<0"><MinusCircle :size="14"/>删除触发器</button><span>修改现有触发器会先删除再创建，请核对 SQL 预览。</span></div><div class="designer-trigger-pane"><div class="designer-trigger-list"><button v-for="(item,i) in model.triggers" :key="item.id" :class="{selected:triggerSelected===i}" @click="triggerSelected=i">{{item.name||'未命名触发器'}}</button></div><div v-if="currentTrigger" class="designer-trigger-editor"><div class="designer-property"><label>名称</label><input v-model="currentTrigger.name" :disabled="locked" aria-label="触发器名称"/><SearchableSelect :id="designerID+'-trigger-timing'" label="触发时机" :modelValue="currentTrigger.timing" @update:modelValue="currentTrigger.timing=$event as DesignTrigger['timing']" :options="['BEFORE','AFTER']" :allowCustom="false" :disabled="locked"/><SearchableSelect :id="designerID+'-trigger-event'" label="触发事件" :modelValue="currentTrigger.event" @update:modelValue="currentTrigger.event=$event as DesignTrigger['event']" :options="['INSERT','UPDATE','DELETE']" :allowCustom="false" :disabled="locked"/></div><textarea v-model="currentTrigger.body" :disabled="locked" spellcheck="false" aria-label="触发器主体"/></div><p v-else class="designer-empty">选择或添加触发器</p></div></template>
 <div v-else-if="tab==='选项'" class="designer-options"><div class="designer-property"><label>表名</label><input v-model="tableName" :disabled="locked||!!savedName" maxlength="64" aria-label="表名" placeholder="请输入表名"/></div><div class="designer-property"><label>存储引擎</label><SearchableSelect :id="designerID+'-engine'" label="存储引擎" v-model="model.options.engine" :options="engines" :disabled="locked"/></div><div class="designer-property"><label>字符集</label><SearchableSelect :id="designerID+'-charset'" label="表字符集" :modelValue="model.options.charset" @update:modelValue="tableCharset($event)" :options="charsets" :disabled="locked"/></div><div class="designer-property"><label>排序规则</label><SearchableSelect :id="designerID+'-collation'" label="表排序规则" :modelValue="model.options.collation" @update:modelValue="tableCollation($event)" :options="collations" :disabled="locked"/></div><div class="designer-property"><label>自增起始值</label><input v-model="model.options.autoIncrement" :disabled="locked" inputmode="numeric" aria-label="自增起始值"/></div><details v-if="model.other.length"><summary>保留的其它约束</summary><pre>{{model.other.join('\n')}}</pre></details></div>
 <div v-else-if="tab==='注释'" class="designer-comment"><label>表注释</label><textarea v-model="model.options.comment" :disabled="locked" aria-label="表注释"/></div>
 <div v-else class="designer-sql"><div class="designer-section-tools"><button class="native-button" @click="copySQL" :disabled="!!sqlState.error||!sqlState.sql"><Copy :size="14"/>复制 SQL</button><span>{{savedName?'仅显示待保存的结构变更':'新建表语句'}} · 保存前请核对</span></div><p v-if="sqlState.error" class="db-tools-error">{{sqlState.error}}</p><textarea v-else :value="sqlState.sql||'-- 没有结构修改'" readonly spellcheck="false" aria-label="表结构 SQL 预览"/></div>

 <footer class="designer-status"><span>{{model.fields.length}} 个字段 · {{model.indexes.length}} 个索引 · {{model.foreignKeys.length}} 个外键</span><span>{{dirty?'设计尚未保存':savedName?'设计已加载':'新建表'}}<template v-if="!savedName"> · 表名在“选项”中填写</template></span></footer>
</section></template>
